window.REV_FLIP=window.REV_FLIP||{};window.REV_FLIP["agentic-ai"]=[{"id":"agentic-ai-f0001","card":"q-agentic-ai-001-agentic-ai-and-agents","sec":"agentic-ai-s002","q":"What is another name for agentic AI?","a":"<p><strong>Autonomous AI</strong>.</p>","hand":true},{"id":"agentic-ai-f0002","card":"q-agentic-ai-001-agentic-ai-and-agents","sec":"agentic-ai-s002","q":"What is an agent in agentic AI?","a":"<p>A program built to perform specific tasks autonomously. It makes decisions from predefined rules or learned patterns. It interacts with users or its environment to achieve goals.</p>","hand":true},{"id":"agentic-ai-f0003","card":"q-agentic-ai-001-agentic-ai-and-agents","sec":"agentic-ai-s002","q":"What path does the Agentic AI Fundamentals course follow, and who is it for?","a":"<p>It runs from agent fundamentals, to internal agent architectures, to machine learning concepts, to practical applications (robotics, healthcare, transportation), to ethics and societal impact. It targets developers who are starting to implement agentic AI.</p>","hand":true},{"id":"agentic-ai-f0004","card":"q-agentic-ai-002-five-characteristics-of-agentic-ai","sec":"agentic-ai-s003","q":"What are the five characteristics of agentic AI?","a":"<ol>\n  <li>Independent decision-making</li>\n  <li>Goal-oriented</li>\n  <li>Learning and evolution</li>\n  <li>Contextual understanding</li>\n  <li>Multi-domain utility</li>\n</ol>","hand":true},{"id":"agentic-ai-f0005","card":"q-agentic-ai-002-five-characteristics-of-agentic-ai","sec":"agentic-ai-s003","q":"What does independent decision-making mean for an agentic AI system?","a":"<p>It operates with minimal human oversight and divides complex workflows into parts. Example: a security camera calls the police when it detects a crime and requests firmware updates on its own.</p>","hand":true},{"id":"agentic-ai-f0006","card":"q-agentic-ai-002-five-characteristics-of-agentic-ai","sec":"agentic-ai-s003","q":"What does it mean that agentic AI is goal-oriented?","a":"<p>It sets its own goals and works to achieve them. Example: the camera sets the goal of fighting crime, detects a crime and reports it.</p>","hand":true},{"id":"agentic-ai-f0007","card":"q-agentic-ai-002-five-characteristics-of-agentic-ai","sec":"agentic-ai-s003","q":"What is the learning and evolution characteristic of agentic AI?","a":"<p>The agent learns from interactions, adapts to new data and improves through machine learning. Example: it notices that weather affects sales and adjusts orders, such as ordering more hardeners when humidity will be high.</p>","hand":true},{"id":"agentic-ai-f0008","card":"q-agentic-ai-002-five-characteristics-of-agentic-ai","sec":"agentic-ai-s003","q":"What is contextual understanding in agentic AI?","a":"<p>The agent understands nuance and mimics human reasoning. Example: it considers weather, time of year and market conditions relevant to a customer's problem.</p>","hand":true},{"id":"agentic-ai-f0009","card":"q-agentic-ai-002-five-characteristics-of-agentic-ai","sec":"agentic-ai-s003","q":"What is multi-domain utility in agentic AI?","a":"<p>The agent finds and uses applications and data across domains and platforms. Examples: customer service, healthcare, retail, manufacturing and cybersecurity.</p>","hand":true},{"id":"agentic-ai-f0010","card":"q-agentic-ai-003-industry-use-cases","sec":"agentic-ai-s004","q":"How did Indaba use agentic AI for insurance?","a":"<p>Indaba, a software development company, built <strong>Morpheus</strong>, an AI industry accelerator. It is a multi-agent system with a specific persona per agent. It handles claims processing, onboarding and data processing. Outcome: lower admin costs, accurate decisions and a personalized customer experience.</p>","hand":true},{"id":"agentic-ai-f0011","card":"q-agentic-ai-003-industry-use-cases","sec":"agentic-ai-s004","q":"How is CrewAI used in the marketing use case?","a":"<p>Collaborative agents each have their own persona (responsibilities and purpose). Agent 1 gathers customer data from social media, Agent 2 analyzes sentiment and Agent 3 generates reports. Outcome: optimized marketing and better-informed strategies.</p>","hand":true},{"id":"agentic-ai-f0012","card":"q-agentic-ai-003-industry-use-cases","sec":"agentic-ai-s004","q":"How does agentic AI help in retail?","a":"<p>It personalizes interactions over email, chat and social media. It uses CRM systems and previous interactions for tailored recommendations and after-sales care. Outcome: better customer loyalty and higher sales.</p>","hand":true},{"id":"agentic-ai-f0013","card":"q-agentic-ai-003-industry-use-cases","sec":"agentic-ai-s004","q":"How does agentic AI help in healthcare?","a":"<p>Multiple agents work on specialized tasks: radiology image analysis, patient history evaluation and treatment recommendation. Outcome: better diagnostics and better quality of care.</p>","hand":true},{"id":"agentic-ai-f0014","card":"q-agentic-ai-004-grey-sloan-medical-center-scenario","sec":"agentic-ai-s005","q":"What challenges did Grey Sloan Medical Center face, and what was the solution?","a":"<p>Challenges: high diagnostic error rates, long patient wait times and inefficient patient data management. The solution was a multi-agent deployment with three groups: diagnostic support agents, patient management agents and administrative agents.</p>","hand":true},{"id":"agentic-ai-f0015","card":"q-agentic-ai-004-grey-sloan-medical-center-scenario","sec":"agentic-ai-s005","q":"What do the diagnostic support agents do at Grey Sloan Medical Center, and what are the results?","a":"<p>They analyze radiology images, lab results and patient histories and give real-time diagnostic recommendations. Results: fewer diagnostic errors and more accurate complex evaluations.</p>","hand":true},{"id":"agentic-ai-f0016","card":"q-agentic-ai-004-grey-sloan-medical-center-scenario","sec":"agentic-ai-s005","q":"What do the patient management agents do at Grey Sloan Medical Center, and what are the results?","a":"<p>They automate scheduling around provider availability and patient needs, optimized with real-time data. Results: 30% more patients seen, fewer cancellations and shorter waits.</p>","hand":true},{"id":"agentic-ai-f0017","card":"q-agentic-ai-004-grey-sloan-medical-center-scenario","sec":"agentic-ai-s005","q":"What do the administrative agents do at Grey Sloan Medical Center, and what are the results?","a":"<p>They automate data entry, update patient records and handle billing and claims. Results: fewer errors and a lower administrative workload.</p>","hand":true},{"id":"agentic-ai-f0018","card":"q-agentic-ai-005-diagnostic-support-agent-flow","sec":"agentic-ai-s006","q":"What is the flow of a diagnostic support agent?","a":"<p>Radiology images, lab results and patient histories go in. ML algorithms analyze the data and send real-time diagnostic recommendations to physicians. The doctor makes the final decision.</p>","hand":true},{"id":"agentic-ai-f0019","card":"q-agentic-ai-005-diagnostic-support-agent-flow","sec":"agentic-ai-s006","q":"What is an example of a diagnostic support agent at work?","a":"<p>The agent examines an X-ray, finds a bone spur and recommends possible treatments. The doctor decides.</p>","hand":true},{"id":"agentic-ai-f0020","card":"q-agentic-ai-005-diagnostic-support-agent-flow","sec":"agentic-ai-s006","q":"What were the overall results of the multi-agent healthcare deployment?","a":"<p>30% more patients per clinic, fewer cancellations, better use of provider time, fewer diagnostic errors and a much lower administrative workload. Staff also had more time for patient care.</p>","hand":true},{"id":"agentic-ai-f0021","card":"q-agentic-ai-005-diagnostic-support-agent-flow","sec":"agentic-ai-s006","q":"Do agents replace humans in the healthcare scenario, and why does each agent get a persona?","a":"<p>No. Agents augment humans and do not replace them. In multi-agent systems each agent gets a specific persona (role and responsibilities) for accuracy and efficiency.</p>","hand":true},{"id":"agentic-ai-f0022","card":"q-agentic-ai-006-environmental-interaction","sec":"agentic-ai-s007","q":"What are the four parts of environmental interaction for an agent?","a":"<p><strong>Sensing, interpreting, deciding, acting</strong>. Sensors gather data, the agent processes and interprets it into insights, makes decisions and takes action. A feedback loop then reassesses the outcome.</p>","hand":true},{"id":"agentic-ai-f0023","card":"q-agentic-ai-006-environmental-interaction","sec":"agentic-ai-s007","q":"Which kinds of data can an agent sense, with examples?","a":"<ul>\n  <li>Image data: a doorbell camera detecting a person</li>\n  <li>Audio: voicemail fraud detection</li>\n  <li>Video: security camera monitoring</li>\n  <li>Other sensors: any data that gives environmental understanding</li>\n</ul>","hand":true},{"id":"agentic-ai-f0024","card":"q-agentic-ai-007-feedback-loop","sec":"agentic-ai-s008","q":"What is a feedback loop in an agentic AI system?","a":"<p>The system learns from its mistakes and refines future responses.</p>","hand":true},{"id":"agentic-ai-f0025","card":"q-agentic-ai-007-feedback-loop","sec":"agentic-ai-s008","q":"What are the four steps of a feedback loop, with the doorbell example?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Step</th><th>Description</th></tr></thead>\n    <tbody>\n      <tr><td>Action taken</td><td>Agent makes an initial assessment (a person is stealing)</td></tr>\n      <tr><td>Outcome sensed</td><td>The result is observed and reassessed</td></tr>\n      <tr><td>Feedback received</td><td>A user or the system corrects it (it is a delivery)</td></tr>\n      <tr><td>Learning</td><td>The agent will not repeat the wrong assumption</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0026","card":"q-agentic-ai-007-feedback-loop","sec":"agentic-ai-s008","q":"What are two examples of agents learning through a feedback loop?","a":"<p>A doorbell camera learns a delivery person is not a thief. A phone fraud detector learns a known friend is not a fraud threat.</p>","hand":true},{"id":"agentic-ai-f0027","card":"q-agentic-ai-008-agent-to-agent-communication","sec":"agentic-ai-s009","q":"Why must agents communicate with each other?","a":"<p>Goals become more complex, so agents must communicate.</p>","hand":true},{"id":"agentic-ai-f0028","card":"q-agentic-ai-008-agent-to-agent-communication","sec":"agentic-ai-s009","q":"What are the three methods of agent-to-agent communication?","a":"<ul>\n  <li><strong>Messaging</strong>: agents share commands, data or information.</li>\n  <li><strong>Shared databases</strong>: persistent data stored and retrieved by multiple agents.</li>\n  <li><strong>Direct interaction</strong>: a durable connection between agents (middleware of agents).</li>\n</ul>","hand":true},{"id":"agentic-ai-f0029","card":"q-agentic-ai-009-agent-coordination","sec":"agentic-ai-s010","q":"What is agent coordination?","a":"<p>The set of strategies and processes that manage interactions between many agents.</p>","hand":true},{"id":"agentic-ai-f0030","card":"q-agentic-ai-009-agent-coordination","sec":"agentic-ai-s010","q":"How does coordination work in the doorbell camera example?","a":"<p>Agent 1 monitors the video feed. Agent 2 spots objects that need identification. Agent 3 decides what object is seen.</p>","hand":true},{"id":"agentic-ai-f0031","card":"q-agentic-ai-009-agent-coordination","sec":"agentic-ai-s010","q":"What are the two components of agentic AI architecture?","a":"<p><strong>Internal processing</strong> (inside each agent) and <strong>communication and coordination</strong> (how agents talk and work together).</p>","hand":true},{"id":"agentic-ai-f0032","card":"q-agentic-ai-010-decision-making-flow","sec":"agentic-ai-s011","q":"Why do planning and problem-solving matter for an agent?","a":"<p>They decide whether an agent adds value or fails outright.</p>","hand":true},{"id":"agentic-ai-f0033","card":"q-agentic-ai-010-decision-making-flow","sec":"agentic-ai-s011","q":"What is the decision-making flow of an agent?","a":"<p>Goal definition, action sequencing, environmental modeling, continual planning.</p>","hand":true},{"id":"agentic-ai-f0034","card":"q-agentic-ai-011-goal-definition","sec":"agentic-ai-s012","q":"When should an agent's objectives be defined?","a":"<p>Clearly, <strong>before deployment</strong>.</p>","hand":true},{"id":"agentic-ai-f0035","card":"q-agentic-ai-011-goal-definition","sec":"agentic-ai-s012","q":"What are examples of simple and complex goals for an agent?","a":"<p>Simple: detect moving targets in front of a camera, or navigate an autonomous car to a location. Complex: formulate an action strategy after an accident, handling injuries and interacting with first responders.</p>","hand":true},{"id":"agentic-ai-f0036","card":"q-agentic-ai-012-action-sequencing","sec":"agentic-ai-s013","q":"What is action sequencing in agent planning?","a":"<p>Defining the sequence of actions that leads the agent to its goal state.</p>","hand":true},{"id":"agentic-ai-f0037","card":"q-agentic-ai-012-action-sequencing","sec":"agentic-ai-s013","q":"What is the action sequence for security camera crime detection?","a":"<ol>\n  <li>Observe the yard.</li>\n  <li>Detect humans.</li>\n  <li>Analyze humans.</li>\n  <li>Determine the humans' intention.</li>\n  <li>Determine risk.</li>\n  <li>Determine trade-offs.</li>\n  <li>Take predefined actions (alert the operator or authorities).</li>\n</ol>","hand":true},{"id":"agentic-ai-f0038","card":"q-agentic-ai-013-environmental-modeling","sec":"agentic-ai-s014","q":"What is environmental modeling for an agent?","a":"<p>Creating a <strong>digital representation</strong> of the physical environment so simulations can find the best outcomes.</p>","hand":true},{"id":"agentic-ai-f0039","card":"q-agentic-ai-013-environmental-modeling","sec":"agentic-ai-s014","q":"What is an example of environmental modeling?","a":"<p>The security camera replicates the yard digitally and models potential movements.</p>","hand":true},{"id":"agentic-ai-f0040","card":"q-agentic-ai-014-continual-planning","sec":"agentic-ai-s015","q":"What is continual planning?","a":"<p>Updating and revising plans as new information arrives and the environment changes.</p>","hand":true},{"id":"agentic-ai-f0041","card":"q-agentic-ai-014-continual-planning","sec":"agentic-ai-s015","q":"What is an example of continual planning?","a":"<p>A bench is moved in the yard. The camera reevaluates the scene, handles image portions differently and redoes its actions around the change.</p>","hand":true},{"id":"agentic-ai-f0042","card":"q-agentic-ai-015-ml-versus-agentic-ai-frameworks","sec":"agentic-ai-s016","q":"What is machine learning, and why does it matter for AI systems?","a":"<p>ML is the theory and methodology of learning from data and making choices without explicit instructions. It is a form of AI and the <strong>foundation for most AI systems</strong>.</p>","hand":true},{"id":"agentic-ai-f0043","card":"q-agentic-ai-015-ml-versus-agentic-ai-frameworks","sec":"agentic-ai-s016","q":"How do agentic AI frameworks relate to machine learning?","a":"<p>Agentic AI frameworks are the practical tools that bring ML theory to life.</p>","hand":true},{"id":"agentic-ai-f0044","card":"q-agentic-ai-016-three-main-ml-models","sec":"agentic-ai-s017","q":"What are the three main ML models, and how does each work?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Model</th><th>How it works</th><th>Example</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Supervised learning</strong></td><td>Learns from labeled data</td><td>Training on labeled images (cat/dog)</td></tr>\n      <tr><td><strong>Unsupervised learning</strong></td><td>Finds hidden patterns in unlabeled data</td><td>Finding customer segments</td></tr>\n      <tr><td><strong>Reinforcement learning</strong></td><td>Trains agents by rewarding positive actions</td><td>Learning optimal behavior through trial and reward</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0045","card":"q-agentic-ai-016-three-main-ml-models","sec":"agentic-ai-s017","q":"What kind of data does supervised learning use, versus unsupervised learning?","a":"<p>Supervised learning learns from labeled data. Unsupervised learning finds hidden patterns in unlabeled data.</p>","hand":true},{"id":"agentic-ai-f0046","card":"q-agentic-ai-017-ml-inside-agents","sec":"agentic-ai-s018","q":"In what two ways can ML be used by an agent?","a":"<p>As an internal system embedded in the agent, or as an external resource used as a service.</p>","hand":true},{"id":"agentic-ai-f0047","card":"q-agentic-ai-017-ml-inside-agents","sec":"agentic-ai-s018","q":"What does ML let an agent do?","a":"<p>Evaluate actions, optimize goals and execute tasks autonomously.</p>","hand":true},{"id":"agentic-ai-f0048","card":"q-agentic-ai-018-continuous-improvement-cycle","sec":"agentic-ai-s019","q":"What is the continuous improvement cycle of agents with embedded ML?","a":"<p>Process new data, refine performance metrics, enhance prediction accuracy, meet challenges with growing robustness, repeat.</p>","hand":true},{"id":"agentic-ai-f0049","card":"q-agentic-ai-018-continuous-improvement-cycle","sec":"agentic-ai-s019","q":"What is the security camera example of continuous improvement?","a":"<p>The camera adjusts its internal cooling from air temperature and humidity. It learns from earlier calculations how much to adjust.</p>","hand":true},{"id":"agentic-ai-f0050","card":"q-agentic-ai-018-continuous-improvement-cycle","sec":"agentic-ai-s019","q":"What is the human analogy for continuous improvement in ML?","a":"<p>You go out without a jacket in the cold, learn it was a bad choice and change your behavior for every later cold day.</p>","hand":true},{"id":"agentic-ai-f0051","card":"q-agentic-ai-019-ml-business-applications","sec":"agentic-ai-s020","q":"What are business applications of ML?","a":"<ul>\n  <li>Spotting fraudulent applications</li>\n  <li>Finding accounting anomalies</li>\n  <li>Identifying patterns in vast datasets</li>\n  <li>Autonomous decision-making without human oversight</li>\n</ul>","hand":true},{"id":"agentic-ai-f0052","card":"q-agentic-ai-020-what-policy-frameworks-are","sec":"agentic-ai-s021","q":"What are policy frameworks for agents?","a":"<p>Guidelines that <strong>control and direct agent actions</strong>, aligned with values and norms set by architects, designers, developers or end users. They structure how the system makes decisions and follows rules.</p>","hand":true},{"id":"agentic-ai-f0053","card":"q-agentic-ai-020-what-policy-frameworks-are","sec":"agentic-ai-s021","q":"Why does an agent system need policies?","a":"<p>Without policies, a system could send personal information without consent or perform illegal or unethical tasks.</p>","hand":true},{"id":"agentic-ai-f0054","card":"q-agentic-ai-020-what-policy-frameworks-are","sec":"agentic-ai-s021","q":"What are the two types of policy framework and their purposes?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Type</th><th>Purpose</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Decision-making framework</strong></td><td>Aligns AI actions with societal, legal and ethical standards</td></tr>\n      <tr><td><strong>Rule-based framework</strong></td><td>Predefined rules for predictable, compliant behavior</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0055","card":"q-agentic-ai-021-decision-making-framework-components","sec":"agentic-ai-s022","q":"What are the components of a decision-making policy framework?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Component</th><th>Description</th><th>Example</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Ethical policies</strong></td><td>Align actions with societal and legal standards</td><td>The system does not break laws or upset users</td></tr>\n      <tr><td><strong>Oversight mechanisms</strong></td><td>Human-in-the-loop or human-on-the-loop</td><td>A kill button to stop operations</td></tr>\n      <tr><td><strong>Risk assessment and mitigation</strong></td><td>Address adverse outcomes of autonomous decisions</td><td>The camera calls police for a crime but avoids bias based on race or age</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0056","card":"q-agentic-ai-021-decision-making-framework-components","sec":"agentic-ai-s022","q":"Human-in-the-loop vs human-on-the-loop?","a":"<p><strong>Human-in-the-loop</strong>: a human is actively involved in decision-making. <strong>Human-on-the-loop</strong>: a human can intervene when necessary.</p>","hand":true},{"id":"agentic-ai-f0057","card":"q-agentic-ai-022-rule-based-framework","sec":"agentic-ai-s023","q":"What are the three elements of a rule-based framework?","a":"<ul>\n  <li><strong>Predefined rules</strong>: specific rules the system must follow, such as never attempting to injure a human.</li>\n  <li><strong>Adaptability</strong>: behavior can change with conditions while still obeying the rules.</li>\n  <li><strong>Compliance</strong>: ensures predictable behavior.</li>\n</ul>","hand":true},{"id":"agentic-ai-f0058","card":"q-agentic-ai-022-rule-based-framework","sec":"agentic-ai-s023","q":"What is an example of a rule-based framework at work?","a":"<p>Altering the material mix in a temperature-sensitive manufacturing process as the weather changes, while still following every safety rule.</p>","hand":true},{"id":"agentic-ai-f0059","card":"q-agentic-ai-023-ongoing-monitoring","sec":"agentic-ai-s024","q":"Why are policy frameworks not set-and-forget, and what is the cycle?","a":"<p>Policies must be monitored and updated. The cycle is: set policies, deploy, monitor AI actions, ensure compliance, then revisit and update the policies.</p>","hand":true},{"id":"agentic-ai-f0060","card":"q-agentic-ai-024-utility-based-frameworks","sec":"agentic-ai-s025","q":"What are utility-based frameworks?","a":"<p>Conceptual structures that guide AI design, deployment and evaluation, maximizing usefulness while balancing risks and benefits.</p>","hand":true},{"id":"agentic-ai-f0061","card":"q-agentic-ai-024-utility-based-frameworks","sec":"agentic-ai-s025","q":"What are the four components of a utility-based framework?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Component</th><th>Description</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Utility functions</strong></td><td>Map outcomes to numerical values and calculate desirability</td></tr>\n      <tr><td><strong>Preference modeling</strong></td><td>Integrates user preferences into the utility function</td></tr>\n      <tr><td><strong>Risk and uncertainty</strong></td><td>Uses probabilistic models to analyze and mitigate risk</td></tr>\n      <tr><td><strong>Trade-off analysis</strong></td><td>Balances competing objectives and constraints</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0062","card":"q-agentic-ai-025-utility-functions-and-preference-modelin","sec":"agentic-ai-s026","q":"What does a utility function do for an agent?","a":"<p>It maps outcomes to numbers so the agent picks the best action mathematically.</p>","hand":true},{"id":"agentic-ai-f0063","card":"q-agentic-ai-025-utility-functions-and-preference-modelin","sec":"agentic-ai-s026","q":"How does a utility function work in the security camera example?","a":"<p>A person carrying an object is detected. The utility function ranks it from 1 (least likely a weapon) to 10 (most likely a weapon). The agent evaluates the threat level and decides whether further observation is needed.</p>","hand":true},{"id":"agentic-ai-f0064","card":"q-agentic-ai-025-utility-functions-and-preference-modelin","sec":"agentic-ai-s026","q":"What is preference modeling?","a":"<p>Setting user preferences and feeding them into the utility function to find the most optimal solution. For example, preferences define how a camera image is optimized for analysis before the agent decides.</p>","hand":true},{"id":"agentic-ai-f0065","card":"q-agentic-ai-026-risk-uncertainty-and-trade-offs","sec":"agentic-ai-s027","q":"How do utility-based frameworks handle risk and uncertainty?","a":"<ul>\n  <li>Probabilistic models determine, analyze, manage and mitigate risks.</li>\n  <li>They account for innate biases in the agentic AI system.</li>\n  <li>They consider the risk tolerance of stakeholders.</li>\n</ul>","hand":true},{"id":"agentic-ai-f0066","card":"q-agentic-ai-026-risk-uncertainty-and-trade-offs","sec":"agentic-ai-s027","q":"What is trade-off analysis, with a human analogy?","a":"<p>It balances competing objectives alongside risk analysis. Analogy: on a cloudy day, take an umbrella (prepared for rain) or leave it (no burden if dry).</p>","hand":true},{"id":"agentic-ai-f0067","card":"q-agentic-ai-027-reinforcement-learning","sec":"agentic-ai-s028","q":"What is reinforcement learning (RL)?","a":"<p>Learning by <strong>interacting with an environment</strong>. The agent takes an action in a state and the environment returns a reward or punishment. The agent learns to maximize rewards and avoid penalties.</p>","hand":true},{"id":"agentic-ai-f0068","card":"q-agentic-ai-027-reinforcement-learning","sec":"agentic-ai-s028","q":"What are practical scenarios for reinforcement learning?","a":"<p>Autonomous driving, and jet engine troubleshooting that automatically finds the safest outcome.</p>","hand":true},{"id":"agentic-ai-f0069","card":"q-agentic-ai-028-q-learning-and-the-q-table","sec":"agentic-ai-s029","q":"What is Q-learning and what is a Q-table?","a":"<p>Q-learning is a type of RL that uses a <strong>Q-table</strong> to track the best action for each situation. The agent updates the table from experience and gradually learns the actions that maximize reward.</p>","hand":true},{"id":"agentic-ai-f0070","card":"q-agentic-ai-028-q-learning-and-the-q-table","sec":"agentic-ai-s029","q":"What does a Q-table look like?","a":"<p>Rows are states and columns are actions, with a value for each pair:</p>\n<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>State</th><th>Action 1</th><th>Action 2</th><th>Action 3</th></tr></thead>\n    <tbody>\n      <tr><td>State A</td><td>0.8</td><td>0.3</td><td>0.1</td></tr>\n      <tr><td>State B</td><td>0.2</td><td>0.9</td><td>0.4</td></tr>\n      <tr><td>State C</td><td>0.5</td><td>0.1</td><td>0.7</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0071","card":"q-agentic-ai-029-six-steps-to-develop-a-q-learning-algori","sec":"agentic-ai-s030","q":"What are the six steps to develop a Q-learning algorithm?","a":"<ol>\n  <li>Define environment</li>\n  <li>Identify states</li>\n  <li>Define actions</li>\n  <li>Establish reward signal</li>\n  <li>Develop policy</li>\n  <li>Define value function</li>\n</ol>\n<p>After these steps the agent interacts, updates the Q-table and keeps improving.</p>","hand":true},{"id":"agentic-ai-f0072","card":"q-agentic-ai-029-six-steps-to-develop-a-q-learning-algori","sec":"agentic-ai-s030","q":"In Q-learning development, what does \"define environment\" mean?","a":"<p>Define all possible states, actions and interaction rules: everything the agent can do and the responses it gets.</p>","hand":true},{"id":"agentic-ai-f0073","card":"q-agentic-ai-029-six-steps-to-develop-a-q-learning-algori","sec":"agentic-ai-s030","q":"In Q-learning development, what is a state to identify?","a":"<p>A representation of the situation at one point in time. Example: dark outside is a state the camera agent understands.</p>","hand":true},{"id":"agentic-ai-f0074","card":"q-agentic-ai-029-six-steps-to-develop-a-q-learning-algori","sec":"agentic-ai-s030","q":"In Q-learning development, what does \"define actions\" mean?","a":"<p>Define the actions the agent can take. Examples: a camera changes aperture for darkness, a jet engine triggers fire suppression.</p>","hand":true},{"id":"agentic-ai-f0075","card":"q-agentic-ai-029-six-steps-to-develop-a-q-learning-algori","sec":"agentic-ai-s030","q":"In Q-learning development, what is the reward signal?","a":"<p>Numerical values received after an action in a state, like a \"digital doggy treat\". The goal is to maximize cumulative reward.</p>","hand":true},{"id":"agentic-ai-f0076","card":"q-agentic-ai-029-six-steps-to-develop-a-q-learning-algori","sec":"agentic-ai-s030","q":"In Q-learning development, what is the policy, and what is an example?","a":"<p>A strategy mapping states to actions. Example: an airline policy never to shut down a jet engine in flight.</p>","hand":true},{"id":"agentic-ai-f0077","card":"q-agentic-ai-029-six-steps-to-develop-a-q-learning-algori","sec":"agentic-ai-s030","q":"In Q-learning development, what is the value function?","a":"<p>It estimates the expected cumulative reward of a state under a policy. It assesses the long-term benefit of states and actions.</p>","hand":true},{"id":"agentic-ai-f0078","card":"q-agentic-ai-030-key-rl-terminology","sec":"agentic-ai-s031","q":"What are the key terms in reinforcement learning?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Term</th><th>Definition</th></tr></thead>\n    <tbody>\n      <tr><td><strong>State</strong></td><td>Current situation or configuration of the environment</td></tr>\n      <tr><td><strong>Action</strong></td><td>What the agent can do in a state</td></tr>\n      <tr><td><strong>Reward</strong></td><td>Numerical feedback after an action</td></tr>\n      <tr><td><strong>Policy</strong></td><td>Strategy mapping states to actions</td></tr>\n      <tr><td><strong>Value function</strong></td><td>Expected cumulative reward from a state following a policy</td></tr>\n      <tr><td><strong>Q-table</strong></td><td>Table tracking the best actions per state (Q-learning only)</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0079","card":"q-agentic-ai-030-key-rl-terminology","sec":"agentic-ai-s031","q":"Which RL term applies to Q-learning only?","a":"<p>The <strong>Q-table</strong>, a table tracking the best actions per state.</p>","hand":true},{"id":"agentic-ai-f0080","card":"q-agentic-ai-030-key-rl-terminology","sec":"agentic-ai-s031","q":"Reward vs value function in RL?","a":"<p>A reward is numerical feedback after an action. The value function is the expected cumulative reward from a state following a policy.</p>","hand":true},{"id":"agentic-ai-f0081","card":"q-agentic-ai-031-major-versus-minor-architectures","sec":"agentic-ai-s032","q":"What is the difference between major and minor agent architectures?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Type</th><th>Role</th><th>Scope</th><th>Example</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Major</strong></td><td>Strategic tasks, the master controller</td><td>Broad, foundational</td><td>How a camera with built-in AI works</td></tr>\n      <tr><td><strong>Minor</strong></td><td>Specific tasks done at the behest of the major architecture</td><td>Narrow, specialized</td><td>Updating firmware, reading air temperature, adjusting aperture</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0082","card":"q-agentic-ai-031-major-versus-minor-architectures","sec":"agentic-ai-s032","q":"Why does the choice of architecture matter?","a":"<p>The architecture you choose defines how the AI processes information, learns and makes decisions.</p>","hand":true},{"id":"agentic-ai-f0083","card":"q-agentic-ai-032-seven-major-architectures","sec":"agentic-ai-s033","q":"What are the seven major agent architectures?","a":"<ol>\n  <li>Single-agent</li>\n  <li>Multi-agent</li>\n  <li>Reflection-based</li>\n  <li>Tool-integrated</li>\n  <li>Planning-centric</li>\n  <li>GAINs (Generative AI Networks)</li>\n  <li>Human-AI collaboration</li>\n</ol>","hand":true},{"id":"agentic-ai-f0084","card":"q-agentic-ai-032-seven-major-architectures","sec":"agentic-ai-s033","q":"What does each major architecture do, with its example?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>#</th><th>Architecture</th><th>Description</th><th>Example</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td><strong>Single-agent</strong></td><td>One agent interacts with the environment</td><td>Well-defined problems with no collaboration</td></tr>\n      <tr><td>2</td><td><strong>Multi-agent</strong></td><td>Multiple agents work together</td><td>Camera agent talks to manufacturer server agents for a firmware upgrade</td></tr>\n      <tr><td>3</td><td><strong>Reflection-based</strong></td><td>Agents critique their own output and refine iteratively</td><td>Camera checks it is really seeing a crime and not someone picking something up</td></tr>\n      <tr><td>4</td><td><strong>Tool-integrated</strong></td><td>Uses external tools beyond pre-programmed capabilities</td><td>Camera uses the internet to look up a home address</td></tr>\n      <tr><td>5</td><td><strong>Planning-centric</strong></td><td>Breaks complex tasks into steps, plans and adapts autonomously</td><td>A 50-step firmware upgrade combined into one step</td></tr>\n      <tr><td>6</td><td><strong>GAINs (Generative AI Networks)</strong></td><td>Multi-agent collaboration using specialized skills</td><td>Camera reaches out to a crime identification agent and a weather prediction agent</td></tr>\n      <tr><td>7</td><td><strong>Human-AI collaboration</strong></td><td>Agents and humans work together</td><td>AI automates routine tasks; humans focus on creativity and problem-solving</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0085","card":"q-agentic-ai-033-single-agent-and-multi-agent","sec":"agentic-ai-s034","q":"What is a single-agent architecture and when does it suit?","a":"<p>One agent interacts with the environment. It suits well-defined problems and needs no feedback from other agents.</p>","hand":true},{"id":"agentic-ai-f0086","card":"q-agentic-ai-033-single-agent-and-multi-agent","sec":"agentic-ai-s034","q":"What is a multi-agent architecture?","a":"<p>Several agents collaborate, with different execution paths, using each agent's specialized capabilities. Example: automated firmware upgrade through camera-to-server communication.</p>","hand":true},{"id":"agentic-ai-f0087","card":"q-agentic-ai-034-reflection-based-and-tool-integrated","sec":"agentic-ai-s035","q":"How does a reflection-based agent work, and why is it useful?","a":"<p>The agent produces output, critiques it, refines it iteratively and reaches a validated decision. Self-critique prevents false positives, such as not calling police on someone just picking something up.</p>","hand":true},{"id":"agentic-ai-f0088","card":"q-agentic-ai-034-reflection-based-and-tool-integrated","sec":"agentic-ai-s035","q":"What is a tool-integrated agent?","a":"<p>An agent that uses a web search engine, image processing software and other external tools to go beyond its pre-programmed functions.</p>","hand":true},{"id":"agentic-ai-f0089","card":"q-agentic-ai-035-planning-centric-gains-and-human-ai-coll","sec":"agentic-ai-s036","q":"What does a planning-centric agent do?","a":"<p>It breaks a complex task (such as 50 steps) into manageable steps, plans and adapts autonomously during execution, and can combine steps for efficiency.</p>","hand":true},{"id":"agentic-ai-f0090","card":"q-agentic-ai-035-planning-centric-gains-and-human-ai-coll","sec":"agentic-ai-s036","q":"What are GAINs in agent architecture?","a":"<p>A form of multi-agent collaboration where agents reach out to others with specialized skills (crime identification, weather prediction) and solve problems together.</p>","hand":true},{"id":"agentic-ai-f0091","card":"q-agentic-ai-035-planning-centric-gains-and-human-ai-coll","sec":"agentic-ai-s036","q":"How are tasks split in human-AI collaboration?","a":"<p>AI handles routine tasks, automation and repetitive processes. Humans focus on creativity, problem-solving and higher-level cognitive functions.</p>","hand":true},{"id":"agentic-ai-f0092","card":"q-agentic-ai-036-three-minor-architectures","sec":"agentic-ai-s037","q":"What are the three minor agent architectures?","a":"<p>Behavior-based, emotion-based and swarm intelligence.</p>","hand":true},{"id":"agentic-ai-f0093","card":"q-agentic-ai-036-three-minor-architectures","sec":"agentic-ai-s037","q":"What is a behavior-based architecture?","a":"<p>It uses specific behavior patterns or models and is closely related to reactive architectures. It is not broadly applicable across domains.</p>","hand":true},{"id":"agentic-ai-f0094","card":"q-agentic-ai-036-three-minor-architectures","sec":"agentic-ai-s037","q":"What is an emotion-based architecture?","a":"<p>It simulates emotional responses such as anger or empathy for more natural, human-like interaction.</p>","hand":true},{"id":"agentic-ai-f0095","card":"q-agentic-ai-036-three-minor-architectures","sec":"agentic-ai-s037","q":"What is swarm intelligence?","a":"<p>It models collective behavior from natural systems such as ant colonies and schools of fish. Simple individual rules produce emergent collective behavior that solves complex problems.</p>","hand":true},{"id":"agentic-ai-f0096","card":"q-agentic-ai-036-three-minor-architectures","sec":"agentic-ai-s037","q":"Can you create your own minor architectures?","a":"<p>Yes. Minor architectures are narrow but important, and you can create custom ones.</p>","hand":true},{"id":"agentic-ai-f0097","card":"q-agentic-ai-037-six-pre-development-components-of-a-coop","sec":"agentic-ai-s038","q":"What are the six pre-development components of a cooperative multi-agent system?","a":"<ol>\n  <li>Define environment</li>\n  <li>Communication protocols</li>\n  <li>Shared goals and rewards</li>\n  <li>Coordination mechanisms</li>\n  <li>Decentralized decision-making</li>\n  <li>Role specialization</li>\n</ol>","hand":true},{"id":"agentic-ai-f0098","card":"q-agentic-ai-037-six-pre-development-components-of-a-coop","sec":"agentic-ai-s038","q":"In a cooperative multi-agent system, what does \"define environment\" cover?","a":"<p>Map all possible states and agent interactions: the physical or digital space agents operate in.</p>","hand":true},{"id":"agentic-ai-f0099","card":"q-agentic-ai-037-six-pre-development-components-of-a-coop","sec":"agentic-ai-s038","q":"What do communication protocols decide in a multi-agent system, with examples?","a":"<p>How agents communicate. Examples: TCP/IP messaging, RFID, Bluetooth, APIs.</p>","hand":true},{"id":"agentic-ai-f0100","card":"q-agentic-ai-037-six-pre-development-components-of-a-coop","sec":"agentic-ai-s038","q":"What are shared goals and rewards in a multi-agent system?","a":"<p>Aligning agents with cooperative reward structures. Example: maximize sales while minimizing costs.</p>","hand":true},{"id":"agentic-ai-f0101","card":"q-agentic-ai-037-six-pre-development-components-of-a-coop","sec":"agentic-ai-s038","q":"What are coordination mechanisms in a multi-agent system?","a":"<p>They organize effort and avoid conflict or redundancy. Examples: leader-follower structures, consensus-driven.</p>","hand":true},{"id":"agentic-ai-f0102","card":"q-agentic-ai-037-six-pre-development-components-of-a-coop","sec":"agentic-ai-s038","q":"What is decentralized decision-making in a multi-agent system?","a":"<p>Each agent decides independently from local or external information. Example: the camera agent keeps working if communication with others fails.</p>","hand":true},{"id":"agentic-ai-f0103","card":"q-agentic-ai-037-six-pre-development-components-of-a-coop","sec":"agentic-ai-s038","q":"What is role specialization in a multi-agent system?","a":"<p>Assigning specific abilities by capability. Example: one agent handles customer chat, another processes orders behind the scenes.</p>","hand":true},{"id":"agentic-ai-f0104","card":"q-agentic-ai-038-why-decentralized-decision-making","sec":"agentic-ai-s039","q":"What happens in a decentralized multi-agent system when Agent A loses communication?","a":"<p>Agent A continues independently while B and C keep talking. This adds <strong>redundancy and resilience</strong>.</p>","hand":true},{"id":"agentic-ai-f0105","card":"q-agentic-ai-039-communication-protocols","sec":"agentic-ai-s040","q":"Why do agents need communication protocols?","a":"<p>Without protocols you get miscommunication, shared errors and security breaches.</p>","hand":true},{"id":"agentic-ai-f0106","card":"q-agentic-ai-039-communication-protocols","sec":"agentic-ai-s040","q":"What are the four parts of agent communication protocols, with implementations?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Step</th><th>Description</th><th>Implementation</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Standardization</strong></td><td>Common rules for communication</td><td>Structured data formats</td></tr>\n      <tr><td><strong>Message formats</strong></td><td>Agreed data structure for exchanging information</td><td>JSON, XML</td></tr>\n      <tr><td><strong>Ontologies</strong></td><td>Shared vocabulary and collective understanding of terms</td><td>Web Ontology Language (OWL)</td></tr>\n      <tr><td><strong>Security</strong></td><td>Protect data integrity and confidentiality</td><td>SSL/TLS, OAuth, digital certificates</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0107","card":"q-agentic-ai-039-communication-protocols","sec":"agentic-ai-s040","q":"What are ontologies in agent communication?","a":"<p>A shared vocabulary and collective understanding of terms. Implementation: Web Ontology Language (OWL).</p>","hand":true},{"id":"agentic-ai-f0108","card":"q-agentic-ai-040-message-format-example","sec":"agentic-ai-s041","q":"In a multi-agent system, what does a JSON alert message from an agent look like (agent ID, message type, timestamp, payload)?","a":"<p>It is a JSON object with the sender's <code>agent_id</code>, a <code>message_type</code>, a <code>timestamp</code> and a nested <code>payload</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">JSON</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>{\n  &quot;agent_id&quot;: &quot;camera_01&quot;,\n  &quot;message_type&quot;: &quot;alert&quot;,\n  &quot;timestamp&quot;: &quot;2024-01-15T10:30:00Z&quot;,\n  &quot;payload&quot;: {\n    &quot;event&quot;: &quot;motion_detected&quot;,\n    &quot;confidence&quot;: 0.92,\n    &quot;action_required&quot;: true\n  }\n}</code></pre></div>","hand":true},{"id":"agentic-ai-f0109","card":"q-agentic-ai-040-message-format-example","sec":"agentic-ai-s041","q":"In an agent message with <code>\"message_type\": \"alert\"</code>, which fields in the <code>payload</code> tell the receiver what happened and how sure the sender is?","a":"<p><code>event</code> names what happened (<code>motion_detected</code>) and <code>confidence</code> gives how sure the sender is (<code>0.92</code>).</p>","hand":true},{"id":"agentic-ai-f0110","card":"q-agentic-ai-040-message-format-example","sec":"agentic-ai-s041","q":"In an agent communication message, which payload field says whether the receiver has to act?","a":"<p><code>action_required</code>, a boolean (<code>true</code> in the <code>camera_01</code> alert message).</p>","hand":true},{"id":"agentic-ai-f0111","card":"q-agentic-ai-041-security-protocols-for-agent-communicati","sec":"agentic-ai-s042","q":"Which three security protocols protect communication between agents, and what does each one do?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Protocol</th><th>Purpose</th></tr></thead>\n    <tbody>\n      <tr><td><strong>SSL/TLS</strong></td><td>Encrypts data in transmission</td></tr>\n      <tr><td><strong>OAuth</strong></td><td>Authentication mechanism</td></tr>\n      <tr><td><strong>Digital certificates</strong></td><td>Verify agent identities on the network</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0112","card":"q-agentic-ai-041-security-protocols-for-agent-communicati","sec":"agentic-ai-s042","q":"Why do agent communication channels use SSL/TLS, OAuth and digital certificates?","a":"<p>They protect sensitive data such as banking information and healthcare records.</p>","hand":true},{"id":"agentic-ai-f0113","card":"q-agentic-ai-041-security-protocols-for-agent-communicati","sec":"agentic-ai-s042","q":"In agent communication security, which protocol verifies agent identities on the network?","a":"<p>Digital certificates.</p>","hand":true},{"id":"agentic-ai-f0114","card":"q-agentic-ai-042-game-theory-in-agentic-ai","sec":"agentic-ai-s043","q":"What is game theory in agentic AI?","a":"<p>A mathematical framework for modeling and analyzing agent behavior and strategic interactions.</p>","hand":true},{"id":"agentic-ai-f0115","card":"q-agentic-ai-042-game-theory-in-agentic-ai","sec":"agentic-ai-s043","q":"In game theory for agentic AI, what are the four core concepts?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Concept</th><th>Description</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Players</strong></td><td>AI agents that use predefined rules, processes and strategies</td></tr>\n      <tr><td><strong>Games</strong></td><td>Scenarios where strategic interactions take place</td></tr>\n      <tr><td><strong>Strategies</strong></td><td>Plans agents follow based on current conditions</td></tr>\n      <tr><td><strong>Payoffs</strong></td><td>Gain or loss calculated from the combined actions of all players</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0116","card":"q-agentic-ai-042-game-theory-in-agentic-ai","sec":"agentic-ai-s043","q":"In game theory, how is a payoff calculated?","a":"<p>It is the gain or loss calculated from the combined actions of all players.</p>","hand":true},{"id":"agentic-ai-f0117","card":"q-agentic-ai-043-types-of-games","sec":"agentic-ai-s044","q":"In game theory for agents, what are the four types of games?","a":"<p>Cooperative, non-cooperative, zero-sum and non-zero-sum.</p>","hand":true},{"id":"agentic-ai-f0118","card":"q-agentic-ai-043-types-of-games","sec":"agentic-ai-s044","q":"In game theory, what is a cooperative game and what is an example?","a":"<p>Agents form alliances for common goals. Example: poker players working as a team and sharing winnings.</p>","hand":true},{"id":"agentic-ai-f0119","card":"q-agentic-ai-043-types-of-games","sec":"agentic-ai-s044","q":"In game theory, what is a non-cooperative game and what is an example?","a":"<p>Agents act independently for individual benefit. Example: agents competing for limited resources.</p>","hand":true},{"id":"agentic-ai-f0120","card":"q-agentic-ai-043-types-of-games","sec":"agentic-ai-s044","q":"In game theory, what is a zero-sum game?","a":"<p>One agent's gain is another's loss, and the total benefit is constant. Example: a fixed budget split between agents.</p>","hand":true},{"id":"agentic-ai-f0121","card":"q-agentic-ai-043-types-of-games","sec":"agentic-ai-s044","q":"In game theory, what is a non-zero-sum game, and why is it useful?","a":"<p>The total benefit can vary. It is often better for defining desired outcomes. Example: collaborative problem-solving where all agents benefit.</p>","hand":true},{"id":"agentic-ai-f0122","card":"q-agentic-ai-043-types-of-games","sec":"agentic-ai-s044","q":"In game theory for agents, how do zero-sum and non-zero-sum games differ?","a":"<p>In zero-sum games the total benefit is constant, so one agent's gain is another's loss. In non-zero-sum games the total benefit can vary, so all agents can benefit.</p>","hand":true},{"id":"agentic-ai-f0123","card":"q-agentic-ai-044-agent-strategies","sec":"agentic-ai-s045","q":"What are the four agent strategies in game theory?","a":"<p>Fixed, deterministic, randomized and probabilistic.</p>","hand":true},{"id":"agentic-ai-f0124","card":"q-agentic-ai-044-agent-strategies","sec":"agentic-ai-s045","q":"In game theory, what is a fixed strategy?","a":"<p>The agent always takes the same action. Example: always play a high-value card.</p>","hand":true},{"id":"agentic-ai-f0125","card":"q-agentic-ai-044-agent-strategies","sec":"agentic-ai-s045","q":"In game theory, what is a deterministic strategy?","a":"<p>The action is determined by the current state. Example: if condition X, always do Y.</p>","hand":true},{"id":"agentic-ai-f0126","card":"q-agentic-ai-044-agent-strategies","sec":"agentic-ai-s045","q":"In game theory, what is a randomized strategy?","a":"<p>The agent chooses randomly between actions. Example: unsure of the opponent, so it randomly attacks or defends.</p>","hand":true},{"id":"agentic-ai-f0127","card":"q-agentic-ai-044-agent-strategies","sec":"agentic-ai-s045","q":"In game theory, what is a probabilistic strategy?","a":"<p>Actions have assigned probabilities. Example: 70% attack, 30% defend.</p>","hand":true},{"id":"agentic-ai-f0128","card":"q-agentic-ai-044-agent-strategies","sec":"agentic-ai-s045","q":"In agent game strategies, how does a randomized strategy differ from a probabilistic one?","a":"<p>A randomized strategy chooses randomly between actions. A probabilistic strategy assigns each action a probability, such as 70% attack and 30% defend.</p>","hand":true},{"id":"agentic-ai-f0129","card":"q-agentic-ai-045-negotiation-protocols","sec":"agentic-ai-s046","q":"What are negotiation protocols in multi-agent systems?","a":"<p>Predefined rules that structure the interaction between agents. They outline the steps, actions and process for reaching consensus.</p>","hand":true},{"id":"agentic-ai-f0130","card":"q-agentic-ai-045-negotiation-protocols","sec":"agentic-ai-s046","q":"In agent negotiation, what is the flow from detecting a violation to resolution?","a":"<p>Agent A detects a violation and tells the other agents. If they disagree, negotiation starts. If agreement is reached, the conflict is resolved. If not, a human is added for resolution.</p>","hand":true},{"id":"agentic-ai-f0131","card":"q-agentic-ai-045-negotiation-protocols","sec":"agentic-ai-s046","q":"In agent negotiation, what happens when the agents cannot reach agreement?","a":"<p>A human is added for resolution.</p>","hand":true},{"id":"agentic-ai-f0132","card":"q-agentic-ai-046-utility-functions-in-negotiation","sec":"agentic-ai-s047","q":"What four roles do utility functions play in agent negotiation?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Role</th><th>Description</th></tr></thead>\n    <tbody>\n      <tr><td>Evaluate options</td><td>Measure how desirable each resolution option is</td></tr>\n      <tr><td>Identify trade-offs</td><td>Separate acceptable from unacceptable trade-offs</td></tr>\n      <tr><td>Maximize utility</td><td>Analyze which outcomes are most optimal</td></tr>\n      <tr><td>Share goals</td><td>Help other agents understand the agent's objectives</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0133","card":"q-agentic-ai-046-utility-functions-in-negotiation","sec":"agentic-ai-s047","q":"In agent negotiation, how does a utility function help identify trade-offs?","a":"<p>It separates acceptable from unacceptable trade-offs.</p>","hand":true},{"id":"agentic-ai-f0134","card":"q-agentic-ai-046-utility-functions-in-negotiation","sec":"agentic-ai-s047","q":"In agent negotiation, what is an example of an agent using its utility function?","a":"<p>An agent with predefined optimized outcomes for product pricing uses its utility function to find the best outcomes. It then communicates its goals to the other agents.</p>","hand":true},{"id":"agentic-ai-f0135","card":"q-agentic-ai-047-conflict-resolution-principles","sec":"agentic-ai-s048","q":"What are the five principles of conflict resolution between agents?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Principle</th><th>Description</th></tr></thead>\n    <tbody>\n      <tr><td>Clear end goals</td><td>Shared goals make resolution possible</td></tr>\n      <tr><td>Prohibited actions</td><td>Define actions agents must never take</td></tr>\n      <tr><td>Fairness and equity</td><td>Modeled on human laws for resolving agreements</td></tr>\n      <tr><td>Learning from interactions</td><td>Agents improve negotiation over time</td></tr>\n      <tr><td>Past outcome analysis</td><td>Use negative outcomes to optimize future negotiations</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0136","card":"q-agentic-ai-047-conflict-resolution-principles","sec":"agentic-ai-s048","q":"In agent conflict resolution, why are clear end goals needed?","a":"<p>Shared goals make resolution possible.</p>","hand":true},{"id":"agentic-ai-f0137","card":"q-agentic-ai-047-conflict-resolution-principles","sec":"agentic-ai-s048","q":"In agent conflict resolution, what are prohibited actions?","a":"<p>Actions that agents must never take.</p>","hand":true},{"id":"agentic-ai-f0138","card":"q-agentic-ai-047-conflict-resolution-principles","sec":"agentic-ai-s048","q":"In agent conflict resolution, what is the fairness and equity principle modeled on?","a":"<p>Human laws for resolving agreements.</p>","hand":true},{"id":"agentic-ai-f0139","card":"q-agentic-ai-048-agent-learning-from-conflict","sec":"agentic-ai-s049","q":"What does an agent do after a conflict is resolved?","a":"<p>It learns from the interaction, improves its negotiation process, analyzes past negative outcomes and optimizes future approaches.</p>","hand":true},{"id":"agentic-ai-f0140","card":"q-agentic-ai-048-agent-learning-from-conflict","sec":"agentic-ai-s049","q":"In agent conflict resolution, how is agent learning compared to humans?","a":"<p>Agents improve automatically, much as humans resolve conflicts differently as they mature.</p>","hand":true},{"id":"agentic-ai-f0141","card":"q-agentic-ai-049-why-ethics-matters","sec":"agentic-ai-s050","q":"In agentic AI, at which stages must ethics be considered?","a":"<p>Every stage: design, build, deployment and operations.</p>","hand":true},{"id":"agentic-ai-f0142","card":"q-agentic-ai-049-why-ethics-matters","sec":"agentic-ai-s050","q":"In agentic AI ethics, what is the bank loan example?","a":"<p>A loan approval system that turns down applications based on race is illegal, damages reputation and is morally wrong. Ethics is not optional.</p>","hand":true},{"id":"agentic-ai-f0143","card":"q-agentic-ai-050-six-ethical-framework-components","sec":"agentic-ai-s051","q":"What are the six components of an ethical framework for agentic AI?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Component</th><th>Description</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Fairness</strong></td><td>Minimize bias and treat all users equitably</td></tr>\n      <tr><td><strong>Transparency</strong></td><td>Openly share processes, data and the logic behind decisions</td></tr>\n      <tr><td><strong>Explainability</strong></td><td>Give clear explanations of AI decisions</td></tr>\n      <tr><td><strong>Accountability</strong></td><td>Governance policies, audit trails, defined liabilities</td></tr>\n      <tr><td><strong>Privacy</strong></td><td>Data minimization and anonymization</td></tr>\n      <tr><td><strong>Data protection</strong></td><td>Prevent unauthorized exposure of personal information</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0144","card":"q-agentic-ai-050-six-ethical-framework-components","sec":"agentic-ai-s051","q":"In an AI ethical framework, how do privacy and data protection differ?","a":"<p>Privacy means data minimization and anonymization. Data protection means preventing unauthorized exposure of personal information.</p>","hand":true},{"id":"agentic-ai-f0145","card":"q-agentic-ai-050-six-ethical-framework-components","sec":"agentic-ai-s051","q":"In an AI ethical framework, how do transparency and explainability differ?","a":"<p>Transparency is openly sharing processes, data and the logic behind decisions. Explainability is giving clear explanations of AI decisions.</p>","hand":true},{"id":"agentic-ai-f0146","card":"q-agentic-ai-051-fairness-frameworks","sec":"agentic-ai-s052","q":"In AI ethics, how do you train bias out of agents?","a":"<p>Use diverse, inclusive datasets so all users are treated equitably regardless of race, gender or age.</p>","hand":true},{"id":"agentic-ai-f0147","card":"q-agentic-ai-051-fairness-frameworks","sec":"agentic-ai-s052","q":"In AI fairness, what must you do with agents and datasets besides using diverse data?","a":"<p>Direct agents on identifying and reducing biases, and make sure datasets represent diverse perspectives.</p>","hand":true},{"id":"agentic-ai-f0148","card":"q-agentic-ai-052-transparency-and-explainability","sec":"agentic-ai-s053","q":"In AI ethics, what is transparency and what is explainability?","a":"<p>Transparency is openly sharing processes, data and the logic behind decisions. Explainability is clearly explaining AI decisions and documenting design and decision-making processes.</p>","hand":true},{"id":"agentic-ai-f0149","card":"q-agentic-ai-052-transparency-and-explainability","sec":"agentic-ai-s053","q":"In AI ethics, what are the benefits of transparency and explainability?","a":"<p>They foster trust and accountability. They meet the \"trust but verify\" process stakeholders want. They create an audit trail with all actions documented.</p>","hand":true},{"id":"agentic-ai-f0150","card":"q-agentic-ai-053-accountability","sec":"agentic-ai-s054","q":"In AI ethics, what are the four aspects of accountability?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Aspect</th><th>Description</th></tr></thead>\n    <tbody>\n      <tr><td>Governance policies</td><td>Procedures that track system behavior</td></tr>\n      <tr><td>Liability definition</td><td>Define who is responsible for harm or errors caused by AI</td></tr>\n      <tr><td>Legal boundaries</td><td>Developers must stay within legal and ethical standards</td></tr>\n      <tr><td>Consequences</td><td>Heavy fines and reputational damage if issues go undiscovered</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0151","card":"q-agentic-ai-053-accountability","sec":"agentic-ai-s054","q":"In AI accountability, what happens if issues go undiscovered?","a":"<p>Heavy fines and reputational damage.</p>","hand":true},{"id":"agentic-ai-f0152","card":"q-agentic-ai-053-accountability","sec":"agentic-ai-s054","q":"In AI accountability, what must systems be able to do?","a":"<p>Keep track of themselves so issues are found and eliminated.</p>","hand":true},{"id":"agentic-ai-f0153","card":"q-agentic-ai-054-privacy-and-data-protection","sec":"agentic-ai-s055","q":"In AI ethics, what are the two privacy principles?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Principle</th><th>Description</th><th>Example</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Data minimization</strong></td><td>Collect only necessary data</td><td>Do not gather unnecessary personal details</td></tr>\n      <tr><td><strong>Anonymization</strong></td><td>Remove anything that links data to a person</td><td>Strip names and IDs from medical records</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0154","card":"q-agentic-ai-054-privacy-and-data-protection","sec":"agentic-ai-s055","q":"In AI privacy, what is anonymization and what is an example?","a":"<p>Removing anything that links data to a person. Example: strip names and IDs from medical records.</p>","hand":true},{"id":"agentic-ai-f0155","card":"q-agentic-ai-054-privacy-and-data-protection","sec":"agentic-ai-s055","q":"In AI privacy, what is a risk example when data protection fails?","a":"<p>An agent exposing your medical history and personal information to an outside entity.</p>","hand":true},{"id":"agentic-ai-f0156","card":"q-agentic-ai-055-ethical-design-checklist","sec":"agentic-ai-s056","q":"What does the ethical design checklist for agentic AI contain?","a":"<ul>\n  <li>Fairness: bias minimized, diverse datasets</li>\n  <li>Transparency: processes and logic openly shared</li>\n  <li>Explainability: decisions clearly documented</li>\n  <li>Accountability: governance policies and audit trails</li>\n  <li>Privacy: data minimization applied</li>\n  <li>Data protection: anonymization enforced</li>\n</ul>","hand":true},{"id":"agentic-ai-f0157","card":"q-agentic-ai-055-ethical-design-checklist","sec":"agentic-ai-s056","q":"In the ethical design checklist for AI, what is the check for accountability?","a":"<p>Governance policies and audit trails.</p>","hand":true},{"id":"agentic-ai-f0158","card":"q-agentic-ai-056-jobs-regulation-and-cybersecurity","sec":"agentic-ai-s057","q":"In AI societal impact, what are the six areas of jobs, regulation and compliance?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Area</th><th>Description</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Job displacement</strong></td><td>Automation may replace existing jobs</td></tr>\n      <tr><td><strong>Job creation</strong></td><td>Potential for more and better-paying jobs; manage the balance with leadership to limit negative impact</td></tr>\n      <tr><td><strong>Regulatory frameworks</strong></td><td>Needed to keep pace with rapid AI advances</td></tr>\n      <tr><td><strong>Global governance</strong></td><td>Governments worldwide are writing laws for responsible AI use</td></tr>\n      <tr><td><strong>Legal personhood</strong></td><td>Debate over agents' legal rights, since agents act like employees with personas and independent decisions</td></tr>\n      <tr><td><strong>Compliance</strong></td><td>Ensure AI is used for good, not harm</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0159","card":"q-agentic-ai-056-jobs-regulation-and-cybersecurity","sec":"agentic-ai-s057","q":"In AI ethics, why is legal personhood debated for agents?","a":"<p>Agents act like employees with personas and independent decisions, so there is a debate over their legal rights.</p>","hand":true},{"id":"agentic-ai-f0160","card":"q-agentic-ai-056-jobs-regulation-and-cybersecurity","sec":"agentic-ai-s057","q":"In AI ethics, what are the three cybersecurity threats and their protections?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Threat</th><th>Protection</th></tr></thead>\n    <tbody>\n      <tr><td>Malicious attacks on AI systems</td><td>Robust security measures</td></tr>\n      <tr><td>Giving up protected data</td><td>Data protection protocols</td></tr>\n      <tr><td>Bad actors controlling agents</td><td>Prevent unauthorized access and manipulation</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0161","card":"q-agentic-ai-056-jobs-regulation-and-cybersecurity","sec":"agentic-ai-s057","q":"In AI ethics, what role must AI agents play, and what is the core principle?","a":"<p>Agents must work as trusted entities, assets to the organization and not security risks. The core principle is do no harm.</p>","hand":true},{"id":"agentic-ai-f0162","card":"q-agentic-ai-057-four-security-challenges","sec":"agentic-ai-s058","q":"What are the four security challenges of agentic AI?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>#</th><th>Challenge</th><th>Description</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td><strong>Unpredictable inputs</strong></td><td>Multi-step user inputs are unpredictable and developers cannot foresee every scenario</td></tr>\n      <tr><td>2</td><td><strong>Complex decision-making</strong></td><td>Internal mechanisms are complex and opaque, so unexpected behavior is hard to trace</td></tr>\n      <tr><td>3</td><td><strong>Diverse environments</strong></td><td>Agents run in environments they were not trained for</td></tr>\n      <tr><td>4</td><td><strong>Untrusted external entities</strong></td><td>Interaction with external systems, humans and data that may not be trustworthy</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0163","card":"q-agentic-ai-057-four-security-challenges","sec":"agentic-ai-s058","q":"In agentic AI security, give an example of the unpredictable inputs challenge.","a":"<p>A customer splits a purchase across multiple credit cards and PayPal, exposing personal data.</p>","hand":true},{"id":"agentic-ai-f0164","card":"q-agentic-ai-057-four-security-challenges","sec":"agentic-ai-s058","q":"In agentic AI security, what risk comes from diverse environments?","a":"<p>Agents run in environments they were not trained for, and new situations bring new security risks.</p>","hand":true},{"id":"agentic-ai-f0165","card":"q-agentic-ai-057-four-security-challenges","sec":"agentic-ai-s058","q":"In agentic AI security, what risks come from untrusted external entities?","a":"<p>Data breaches, manipulation, and agents reprogrammed to work against you.</p>","hand":true},{"id":"agentic-ai-f0166","card":"q-agentic-ai-058-unpredictable-inputs-in-depth","sec":"agentic-ai-s059","q":"In agentic AI security, what happens when a customer splits payment across Card 1, Card 2 and PayPal?","a":"<p>The agent has no security approach for that sequence, and personal data is exposed. There is no malicious intent, only an unforeseen scenario.</p>","hand":true},{"id":"agentic-ai-f0167","card":"q-agentic-ai-058-unpredictable-inputs-in-depth","sec":"agentic-ai-s059","q":"In agentic AI security, why is \"we did not foresee it\" not acceptable for unpredictable inputs?","a":"<p>Developers must identify potential risks during development.</p>","hand":true},{"id":"agentic-ai-f0168","card":"q-agentic-ai-059-complex-and-opaque-decision-making","sec":"agentic-ai-s060","q":"In agentic AI security, why is complex and opaque decision-making a security problem?","a":"<p>Input goes through complex internal mechanisms to output. Unexpected behavior, errors and security vulnerabilities are difficult to trace inside them.</p>","hand":true},{"id":"agentic-ai-f0169","card":"q-agentic-ai-060-untrusted-external-entities","sec":"agentic-ai-s061","q":"In agentic AI security, which external entities can an agent interact with, and what is the risk of each?","a":"<ul>\n  <li>Other systems may be compromised.</li>\n  <li>Other humans may be malicious.</li>\n  <li>Owned data may be corrupted.</li>\n  <li>Unowned data may be manipulated.</li>\n</ul>","hand":true},{"id":"agentic-ai-f0170","card":"q-agentic-ai-060-untrusted-external-entities","sec":"agentic-ai-s061","q":"In agentic AI security, what are the risks of untrusted external entities?","a":"<p>Data breaches, manipulation, and agent reprogramming by bad actors.</p>","hand":true},{"id":"agentic-ai-f0171","card":"q-agentic-ai-060-untrusted-external-entities","sec":"agentic-ai-s061","q":"In agentic AI security, is there a perfect solution, and what should you do?","a":"<p>No perfect security solution exists. Understand the challenges first, then reduce risk.</p>","hand":true},{"id":"agentic-ai-f0172","card":"q-agentic-ai-061-robustness-versus-fault-tolerance","sec":"agentic-ai-s062","q":"In agentic AI reliability, what is robustness and what is fault tolerance?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Concept</th><th>Goal</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Robustness</strong></td><td>The system operates correctly under diverse or unexpected conditions</td></tr>\n      <tr><td><strong>Fault tolerance</strong></td><td>The system keeps operating when components fail</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0173","card":"q-agentic-ai-061-robustness-versus-fault-tolerance","sec":"agentic-ai-s062","q":"In agentic AI reliability, how do robustness and fault tolerance differ?","a":"<p>Robustness is about operating correctly under diverse or unexpected conditions. Fault tolerance is about continuing to operate when components fail.</p>","hand":true},{"id":"agentic-ai-f0174","card":"q-agentic-ai-062-five-reliability-strategies","sec":"agentic-ai-s063","q":"What are the five reliability strategies for agentic AI?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>#</th><th>Strategy</th><th>Description</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td><strong>Redundancy</strong></td><td>Backup agents take over if the primary fails</td></tr>\n      <tr><td>2</td><td><strong>Error detection and correction</strong></td><td>Identify and fix mistakes automatically</td></tr>\n      <tr><td>3</td><td><strong>Robust training data</strong></td><td>Diverse, comprehensive data covering a wide range of scenarios</td></tr>\n      <tr><td>4</td><td><strong>System monitoring and diagnostics</strong></td><td>Real-time performance tracking and issue detection</td></tr>\n      <tr><td>5</td><td><strong>Graceful degradation</strong></td><td>Keep operating in a reduced state instead of failing completely</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0175","card":"q-agentic-ai-062-five-reliability-strategies","sec":"agentic-ai-s063","q":"In agentic AI reliability, which strategy keeps the system operating in a reduced state instead of failing completely?","a":"<p>Graceful degradation.</p>","hand":true},{"id":"agentic-ai-f0176","card":"q-agentic-ai-063-redundancy","sec":"agentic-ai-s064","q":"In agentic AI reliability, what is redundancy?","a":"<p>Running two agents in production so one continues if the other stops, like a whole-house generator for backup power.</p>","hand":true},{"id":"agentic-ai-f0177","card":"q-agentic-ai-063-redundancy","sec":"agentic-ai-s064","q":"In agentic AI reliability, what is automatic failover?","a":"<p>It switches to the backup agent when the primary goes down.</p>","hand":true},{"id":"agentic-ai-f0178","card":"q-agentic-ai-064-error-detection-and-correction","sec":"agentic-ai-s065","q":"In agentic AI reliability, what are the steps of error detection and correction?","a":"<p>The agent processes data, an error detection algorithm finds a mistake, a self-correction technique is applied, and the agent adjusts its action. No human is involved.</p>","hand":true},{"id":"agentic-ai-f0179","card":"q-agentic-ai-064-error-detection-and-correction","sec":"agentic-ai-s065","q":"In agentic AI reliability, what is an example of error detection and correction?","a":"<p>The agent finds an incorrect zip code in an order and corrects it, avoiding a wrong shipment.</p>","hand":true},{"id":"agentic-ai-f0180","card":"q-agentic-ai-065-robust-training-data","sec":"agentic-ai-s066","q":"In agentic AI reliability, what does robust training data look like and why does it help?","a":"<p>It is diverse and comprehensive data that covers a wide range of scenarios and handles unexpected situations. More exposure means better problem-solving.</p>","hand":true},{"id":"agentic-ai-f0181","card":"q-agentic-ai-065-robust-training-data","sec":"agentic-ai-s066","q":"In agentic AI reliability, what analogy explains why more training data helps?","a":"<p>Adults understand more than children because of more experience.</p>","hand":true},{"id":"agentic-ai-f0182","card":"q-agentic-ai-066-system-monitoring-and-diagnostics","sec":"agentic-ai-s067","q":"In agentic AI reliability, what four things make up system monitoring and diagnostics?","a":"<ul>\n  <li>Continuous monitoring tracks agent performance and health in real time.</li>\n  <li>Diagnostic tools scan system behavior to find issues.</li>\n  <li>Root cause analysis finds the causes of false or unexpected actions.</li>\n  <li>Auto-fix keeps the system running.</li>\n</ul>","hand":true},{"id":"agentic-ai-f0183","card":"q-agentic-ai-066-system-monitoring-and-diagnostics","sec":"agentic-ai-s067","q":"In agentic AI reliability, what does root cause analysis do?","a":"<p>It finds the causes of false or unexpected actions.</p>","hand":true},{"id":"agentic-ai-f0184","card":"q-agentic-ai-067-graceful-degradation","sec":"agentic-ai-s068","q":"In agentic AI reliability, what are the stages of graceful degradation?","a":"<p>Normal operation with full functionality, then degraded mode (reduced but operational), then safe operational mode (minimum functionality, minimum harm).</p>","hand":true},{"id":"agentic-ai-f0185","card":"q-agentic-ai-067-graceful-degradation","sec":"agentic-ai-s068","q":"In agentic AI reliability, what does graceful degradation avoid?","a":"<p>Complete failure (total shutdown). Maintain some functions rather than none.</p>","hand":true},{"id":"agentic-ai-f0186","card":"q-agentic-ai-068-security-versus-reliability","sec":"agentic-ai-s069","q":"In agentic AI, how do security and reliability differ in focus and strategies?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Category</th><th>Focus</th><th>Strategies</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Security</strong></td><td>Protect from threats</td><td>Handle unpredictable inputs, trace complex decisions, manage diverse environments, guard against untrusted entities</td></tr>\n      <tr><td><strong>Reliability</strong></td><td>Keep the system running</td><td>Redundancy, error detection, robust training, monitoring, graceful degradation</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0187","card":"q-agentic-ai-068-security-versus-reliability","sec":"agentic-ai-s069","q":"In agentic AI, what is emerging as a discipline and career path in long-term operations?","a":"<p>Long-term AI operations.</p>","hand":true},{"id":"agentic-ai-f0188","card":"q-agentic-ai-069-future-capabilities-in-industry-4-0","sec":"agentic-ai-s070","q":"In Industry 4.0, where is agentic AI moving?","a":"<p>Toward autonomously analyzing vast data to train itself. This enables real-time decision-making and optimization of industrial processes.</p>","hand":true},{"id":"agentic-ai-f0189","card":"q-agentic-ai-069-future-capabilities-in-industry-4-0","sec":"agentic-ai-s070","q":"In Industry 4.0, what are the five future capabilities of agentic AI?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Capability</th><th>Description</th><th>Example</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Self-training</strong></td><td>Analyzes data to train itself</td><td>Frees humans from manual training</td></tr>\n      <tr><td><strong>Real-time decision-making</strong></td><td>Optimizes processes instantly</td><td>Manufacturing systems, bank loan applications</td></tr>\n      <tr><td><strong>Predictive maintenance</strong></td><td>Predicts maintenance before failures</td><td>Install new bushings on an industrial robot before the old ones fail</td></tr>\n      <tr><td><strong>Supply chain optimization</strong></td><td>Predicts demand, automates inventory, streamlines logistics</td><td>Coordinate chip procurement from multiple suppliers</td></tr>\n      <tr><td><strong>Human-robot collaboration</strong></td><td>Robots and humans work side by side</td><td>Robot installs a windshield, human solves novel problems</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0190","card":"q-agentic-ai-069-future-capabilities-in-industry-4-0","sec":"agentic-ai-s070","q":"In Industry 4.0, what is self-training in agentic AI?","a":"<p>The agent analyzes data to train itself, which frees humans from manual training.</p>","hand":true},{"id":"agentic-ai-f0191","card":"q-agentic-ai-070-predictive-maintenance-and-asset-managem","sec":"agentic-ai-s071","q":"In agentic AI, how does predictive maintenance work?","a":"<p>The agent continuously monitors machinery, analyzes workloads and work patterns, predicts maintenance needs before alarms, and schedules proactive maintenance.</p>","hand":true},{"id":"agentic-ai-f0192","card":"q-agentic-ai-070-predictive-maintenance-and-asset-managem","sec":"agentic-ai-s071","q":"In agentic AI, what are the benefits of predictive maintenance?","a":"<p>It reduces downtime and extends asset lifespan.</p>","hand":true},{"id":"agentic-ai-f0193","card":"q-agentic-ai-070-predictive-maintenance-and-asset-managem","sec":"agentic-ai-s071","q":"In agentic AI, what is the cost example for predictive maintenance?","a":"<p>$20 million per year in breakdowns without predictive maintenance versus $1 million per year with it.</p>","hand":true},{"id":"agentic-ai-f0194","card":"q-agentic-ai-071-supply-chain-optimization","sec":"agentic-ai-s072","q":"In agentic AI, what do agents do for supply chain optimization?","a":"<p>They predict demand, automate inventory management, streamline logistics and coordinate suppliers using perfect information.</p>","hand":true},{"id":"agentic-ai-f0195","card":"q-agentic-ai-071-supply-chain-optimization","sec":"agentic-ai-s072","q":"In agentic AI, what is the pandemic example for supply chain optimization?","a":"<p>Cars and trucks sat in storage waiting for a specific chip. Agentic AI would have obtained that chip from any of many suppliers automatically.</p>","hand":true},{"id":"agentic-ai-f0196","card":"q-agentic-ai-071-supply-chain-optimization","sec":"agentic-ai-s072","q":"In agentic AI, what are the benefits of supply chain optimization?","a":"<p>Efficiency, lower cost, customer satisfaction, on-time delivery and better resource use.</p>","hand":true},{"id":"agentic-ai-f0197","card":"q-agentic-ai-072-human-robot-collaboration","sec":"agentic-ai-s073","q":"In agentic AI manufacturing, what do robots handle and what do humans handle?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Robots handle</th><th>Humans handle</th></tr></thead>\n    <tbody>\n      <tr><td>Repetitive, automatable tasks</td><td>Innovative problem-solving</td></tr>\n      <tr><td>Precision tasks (installing windshields)</td><td>Creativity</td></tr>\n      <tr><td>Dangerous tasks</td><td>Strategic decision-making</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0198","card":"q-agentic-ai-072-human-robot-collaboration","sec":"agentic-ai-s073","q":"In agentic AI, what are the benefits of human-robot collaboration?","a":"<p>Precision, safety, and flexible, adaptable manufacturing.</p>","hand":true},{"id":"agentic-ai-f0199","card":"q-agentic-ai-073-five-technology-integrations","sec":"agentic-ai-s074","q":"What are the five technology integrations for agentic AI and their benefits?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Technology</th><th>Integration benefit</th><th>Example</th></tr></thead>\n    <tbody>\n      <tr><td><strong>IoT</strong></td><td>Smart, interconnected systems that collect, analyze and act on data autonomously</td><td>Smart thermostats with AI agents</td></tr>\n      <tr><td><strong>Edge computing</strong></td><td>Process AI near the data source, cutting latency and bandwidth</td><td>Thermostat decides locally without sending data to a master computer</td></tr>\n      <tr><td><strong>Blockchain</strong></td><td>Better data security, transparency and traceability</td><td>Supply chain with a distributed ledger for data integrity</td></tr>\n      <tr><td><strong>Cloud computing</strong></td><td>Seamless updates and continuous learning for agents</td><td>AWS, Microsoft and Google build agentic AI development and operations tools</td></tr>\n      <tr><td><strong>5G</strong></td><td>High-speed, low-latency real-time communication</td><td>Autonomous vehicles, smart cities, remote industrial automation</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0200","card":"q-agentic-ai-073-five-technology-integrations","sec":"agentic-ai-s074","q":"In agentic AI technology integration, which technology cuts latency and bandwidth by processing AI near the data source?","a":"<p>Edge computing.</p>","hand":true},{"id":"agentic-ai-f0201","card":"q-agentic-ai-073-five-technology-integrations","sec":"agentic-ai-s074","q":"In agentic AI technology integration, which technology gives high-speed, low-latency real-time communication, and what are its examples?","a":"<p>5G. Examples: autonomous vehicles, smart cities, remote industrial automation.</p>","hand":true},{"id":"agentic-ai-f0202","card":"q-agentic-ai-074-iot-and-edge-computing","sec":"agentic-ai-s075","q":"In agentic AI, how does IoT work?","a":"<p>Devices (sensors, thermostats, cameras) collect data autonomously, an agent analyzes it and acts. Together they form a smart interconnected system.</p>","hand":true},{"id":"agentic-ai-f0203","card":"q-agentic-ai-074-iot-and-edge-computing","sec":"agentic-ai-s075","q":"In agentic AI, how does edge computing differ from the traditional approach?","a":"<p>Traditionally a device sends data over the network to a master computer, which decides and sends back a response. With edge computing the device runs the agent and decides locally.</p>","hand":true},{"id":"agentic-ai-f0204","card":"q-agentic-ai-074-iot-and-edge-computing","sec":"agentic-ai-s075","q":"In agentic AI, what are the benefits of edge computing?","a":"<p>It reduces latency and bandwidth, and keeps working when the network is down.</p>","hand":true},{"id":"agentic-ai-f0205","card":"q-agentic-ai-075-blockchain-cloud-and-5g","sec":"agentic-ai-s076","q":"In agentic AI, what does blockchain provide and what do agents provide?","a":"<p>Blockchain provides data security, transparency, traceability, a distributed ledger that is hard to trick, and data authenticity. Agents provide real-time logistics optimization, inventory automation, intelligent decisions, settlement coordination and pattern recognition.</p>","hand":true},{"id":"agentic-ai-f0206","card":"q-agentic-ai-075-blockchain-cloud-and-5g","sec":"agentic-ai-s076","q":"In agentic AI, what does cloud computing provide?","a":"<p>Scalable infrastructure, seamless agent updates and continuous learning.</p>","hand":true},{"id":"agentic-ai-f0207","card":"q-agentic-ai-075-blockchain-cloud-and-5g","sec":"agentic-ai-s076","q":"In agentic AI, why does 5G matter for autonomous agents?","a":"<p>Autonomous agents need ubiquitous communication, and 5G gives high speed with low latency for vehicles, smart cities and remote industrial automation.</p>","hand":true},{"id":"agentic-ai-f0208","card":"q-agentic-ai-076-recommended-next-steps","sec":"agentic-ai-s077","q":"In an agentic AI career, what are the recommended next steps?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Action</th><th>Description</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Continue learning</strong></td><td>Podcasts, YouTube channels, blogs, courses</td></tr>\n      <tr><td><strong>Try agentic tools</strong></td><td>Free or low-cost cloud-based tools for creating AI agents give hands-on experience</td></tr>\n      <tr><td><strong>Change jobs or career</strong></td><td>AI professionals are in high demand across development, security, governance and operations</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"agentic-ai-f0209","card":"q-agentic-ai-076-recommended-next-steps","sec":"agentic-ai-s077","q":"In agentic AI careers, what is the job outlook?","a":"<p>Agentic AI experts are in high demand, most jobs pay well, and many businesses will train and mentor.</p>","hand":true},{"id":"agentic-ai-f0210","card":"q-agentic-ai-077-the-vision","sec":"agentic-ai-s078","q":"In agentic AI, what is the vision for the technology?","a":"<p>AI that does not just follow commands but understands, anticipates and collaborates with people.</p>","hand":true},{"id":"agentic-ai-f0211","card":"q-agentic-ai-077-the-vision","sec":"agentic-ai-s078","q":"In agentic AI, how should technology amplify humanity?","a":"<p>Through responsibility, creativity and ethical commitment, with innovation and ethical decision-making going hand in hand.</p>","hand":true},{"id":"agentic-ai-f0212","card":"q-agentic-ai-078-course-topic-recap","sec":"agentic-ai-s079","q":"In the agentic AI course, what are the key concepts of the security and robustness topic?","a":"<p>Unpredictable inputs, redundancy, graceful degradation.</p>","hand":true},{"id":"agentic-ai-f0213","card":"q-agentic-ai-078-course-topic-recap","sec":"agentic-ai-s079","q":"In the agentic AI course, what are the key concepts of the multi-agent systems topic?","a":"<p>Communication protocols, game theory, negotiation.</p>","hand":true},{"id":"agentic-ai-f0214","card":"q-agentic-ai-078-course-topic-recap","sec":"agentic-ai-s079","q":"In the agentic AI course, what are the key concepts of the ethics and societal impact topic?","a":"<p>Fairness, transparency, accountability, privacy.</p>","hand":true},{"id":"agentic-ai-f0215","card":"q-agentic-ai-078-course-topic-recap","sec":"agentic-ai-s079","q":"In the agentic AI course, what are the key concepts of the future and integration topic?","a":"<p>IoT, edge, blockchain, cloud, 5G.</p>","hand":true},{"id":"agentic-ai-f0216","card":"q-agentic-ai-078-course-topic-recap","sec":"agentic-ai-s079","q":"In the agentic AI course, what are the key concepts of the RL and Q-learning topic?","a":"<p>Q-table, states, actions, rewards, policy, value function.</p>","hand":true},{"id":"agentic-ai-f0217","card":"q-agentic-ai-078-course-topic-recap","sec":"agentic-ai-s079","q":"In the agentic AI course, what are the key concepts of the utility-based frameworks topic?","a":"<p>Utility functions, preference modeling, trade-off analysis.</p>","hand":true},{"id":"agentic-ai-f0218","card":"q-agentic-ai-078-course-topic-recap","sec":"agentic-ai-s079","q":"In the agentic AI course, what are the key concepts of the decision making topic?","a":"<p>Goal definition, action sequencing, environmental modeling.</p>","hand":true},{"id":"agentic-ai-f0219","card":"q-agentic-ai-078-course-topic-recap","sec":"agentic-ai-s079","q":"In the agentic AI course, what are the key concepts of the ML for agents topic?","a":"<p>Supervised, unsupervised, reinforcement learning.</p>","hand":true},{"id":"agentic-ai-f0220","card":"q-agentic-ai-078-course-topic-recap","sec":"agentic-ai-s079","q":"In the agentic AI course, what are the key concepts of the what is agentic AI topic?","a":"<p>Autonomous agents, five characteristics.</p>","hand":true},{"id":"agentic-ai-f0221","card":"q-agentic-ai-078-course-topic-recap","sec":"agentic-ai-s079","q":"In the agentic AI course, what are the key concepts of the applications and use cases topic?","a":"<p>Insurance, marketing, retail, healthcare.</p>","hand":true},{"id":"agentic-ai-f0222","card":"q-agentic-ai-078-course-topic-recap","sec":"agentic-ai-s079","q":"In the agentic AI course, what are the key concepts of the healthcare scenario topic?","a":"<p>Diagnostic, patient management, administrative agents.</p>","hand":true},{"id":"agentic-ai-f0223","card":"q-agentic-ai-078-course-topic-recap","sec":"agentic-ai-s079","q":"In the agentic AI course, what are the key concepts of the environment perception topic?","a":"<p>Sensing, interpreting, feedback loops.</p>","hand":true},{"id":"agentic-ai-f0224","card":"q-agentic-ai-078-course-topic-recap","sec":"agentic-ai-s079","q":"In the agentic AI course, what are the key concepts of the policy frameworks topic?","a":"<p>Decision-making and rule-based frameworks.</p>","hand":true},{"id":"agentic-ai-f0225","card":"q-agentic-ai-078-course-topic-recap","sec":"agentic-ai-s079","q":"In the agentic AI course, what are the key concepts of the architectures topic?","a":"<p>Seven major, three minor.</p>","hand":true}];
